// --- Thread Creation (C++ std::thread)
void task_fn(int id) { /* work */ }
std::thread t1(task_fn, 1);
t1.join(); // Wait for completion
// t1.detach(); // Run independently

// --- Mutex (Mutual Exclusion)
std::mutex mtx;
void protected_access() {
    std::lock_guard<std::mutex> lock(mtx);
    // Only one thread here at a time
}

// --- Condition Variables (Waiting/Notification)
std::condition_variable cv;
std::mutex mtx;
bool ready = false;
void waiter() {
    std::unique_lock<std::mutex> lk(mtx);
    cv.wait(lk, []{ return ready; });
}
void notifier() {
    { std::lock_guard<std::mutex> lk(mtx); ready = true; }
    cv.notify_one(); // or notify_all()
}

// --- Atomic Operations (Lock-Free Counters)
std::atomic<int> counter{0};
void increment() {
    counter.fetch_add(1); // Highly efficient increment
}

// --- Futures/Promises (Asynchronous Results)
int heavy_calc(int x) { return x * 2; }
std::future<int> fut =
    std::async(std::launch::async, heavy_calc, 21);
int result = fut.get(); // Blocking wait for result

// --- Readers-Writer Lock (Shared Mutex)
std::shared_mutex rw_mtx;
// Reader 1 (Shared Access)
std::shared_lock<std::shared_mutex> r1(rw_mtx);
// Writer (Exclusive Access)
std::unique_lock<std::shared_mutex> w(rw_mtx);

// --- Semaphore (Resource Limiting, C++20)
std::counting_semaphore<5> sem(5); // Permits 5 resources
void use_resource() {
    sem.acquire();
    // Critical Section (Resource used)
    sem.release();
}
